//! Rust port of the C++ `indicators` header, reconstructed black-box from
//! test5.cpp's call sites plus the reference binary's 29 bytes of stdout.

pub mod format;
pub mod progress_builder;
pub mod progress_tracker;

pub use self::format::Format;
pub use self::progress_builder::ProgressBuilder;
pub use self::progress_tracker::ProgressTracker;

/// Completion fraction shared by `ProgressBuilder::build` and
/// `ProgressTracker::get_percentage`.
///
/// Divide first in `f32`, then let `Format::percentage` multiply by 100 M-bM-^@M-^T this is
/// the order the reference binary uses, and it is float-only, so `total == 0`
/// yields inf/NaN instead of panicking (an integer `progress * 100 / total`
/// would panic in Rust).
pub(crate) fn ratio(progress: i32, total: i32) -> f32 {
    progress as f32 / total as f32
}
===== src/indicators/format.rs =====
//! Port of the C++ `indicators::Format` static-member helper.

/// The C++ default argument on `percentage(float value, int precision = 1)`.
pub const DEFAULT_PRECISION: usize = 1;

/// Stateless holder for the formatting helpers, mirroring the C++ class that
/// only ever exposes static members.
pub struct Format;

impl Format {
    /// C++ `Format::percentage(value)` M-bM-^@M-^T the call form that takes the default
    /// `precision = 1`. Line 4 of the expected output ("33.0%") uses it.
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, DEFAULT_PRECISION)
    }

    /// C++ `Format::percentage(value, precision)`:
    /// `oss << std::fixed << std::setprecision(precision) << (value * 100.0f) << "%"`.
    ///
    /// The multiply happens in `f32` (the product is rounded back to `f32`) and is
    /// then widened to `f64` for rendering, mirroring the `mulss` + `cvtss2sd`
    /// pipeline of an `ostream << float` insertion. Rust's `{:.N$}` is the exact
    /// equivalent of `std::fixed` + `setprecision(N)`: exactly N fractional digits,
    /// never scientific notation, trailing zeros preserved, round-half-to-even on
    /// the exact binary value.
    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        let scaled = f64::from(value * 100.0f32);
        format!("{scaled:.precision$}%")
    }
}
